import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test.describe("sign out", () => {
  test("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
    // Arrange: signing in sets the session cookie on this request context's cookie jar.
    const login = await request.post("/api/auth/login", {
      data: { email: USERS.member, password: PASSWORD },
    });
    await expectStatus(login, 200);

    // Act
    const logout = await request.post("/api/auth/logout");

    // Assert: status is 204 and the session cookie is cleared in the response.
    expect(logout.status()).toBe(204);
    const setCookies = logout
      .headersArray()
      .filter((h) => h.name.toLowerCase() === "set-cookie")
      .map((h) => h.value);
    const sessionClear = setCookies.find((value) => value.startsWith("session="));
    expect(sessionClear, "logout response should set the session cookie").toBeDefined();
    expect(sessionClear).toMatch(/max-age=0|expires=Thu, 01 Jan 1970/i);
  });
});
